"""The wheeled bimanual YAM Ultra cart (assets/robots/yam_cart_yam_ultra.xml, generated by robots/build_models.py) in
Newton, kinematic inside SolverVBD, plus MuJoCo-side kinematics (IK / FK on the very same MJCF).

Pattern from the Franka Newton cable (~/projects/franka-deformables/run_newton/run_cable.py):
- the robot is added FIRST to both a robot-only model (forward kinematics on the GPU) and the station model, so its
  bodies have the same indices in both;
- every robot body has zero mass and the KINEMATIC flag: VBD never moves it, we write its pose every substep
  (joint positions interpolated between per-frame targets, FK, copied into both VBD states);
- arm joints follow IK solutions (position control of a stiff arm: a 30 g plug cannot push a YAM off its path);
- the gripper is force-controlled: its closing is stopped by the squeeze measured with VBD's own contact law on the
  fingertip pad boxes.

Collision: fingertip pad boxes (8 x 30 x 39.5 mm, I2RT linear_4310 distal 4 cm, from robots/measure_gripper.py),
palm boxes, and convex hulls of the arm link meshes (same as the Genesis robot helper). The cart's boxes do not
collide (they never reach the table).

Joint coordinates are the MJCF's own (19: base_x, base_y, base_yaw, left 1..8, right 1..8), identical in Newton and
MuJoCo. The cart is parked by setting base_y = layout.ROBOT_MOUNT["cart_center_y"] in both (no extra xform).
"""
import json
import math
import os
import sys

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, ROOT)
import layout  # noqa: E402
import ncable as NC  # noqa: E402
import warp as wp  # noqa: E402
import newton  # noqa: E402

MJCF = os.path.join(ROOT, "assets", "robots", "yam_cart_yam_ultra.xml")
EXPORT_INDEX = os.path.join(ROOT, "assets", "robots", "export", "yam_ultra", "index.json")
SIDES = ("left", "right")
TCP_OFFSET = np.array([3.8898e-05, 9.681e-05, 0.14465])  # I2RT grasp_site in the <side>_gripper (flange) frame
FINGER_Q_MAX = 0.0475
PAD_GAP0 = 0.001  # pad gap = 2 q + PAD_GAP0
FINGER_SPEED = 0.05  # m/s per finger (I2RT linear_4310 class)
PAD_KE, PAD_MU = 2.0e4, 1.0  # rubberised fingertip pads (MJCF friction 1.0)
LINK_KE, LINK_MU = 1.0e5, 0.4  # aluminium / anodised links
HOME_TCP = dict(left=(-0.26, -0.22, layout.TABLE_TOP_Z + 0.20), right=(0.26, -0.22, layout.TABLE_TOP_Z + 0.20))

# MJCF rgba -> compositor material (robots/yam_cart.py MATERIALS)
MATERIALS = {
    "anodised_black": dict(kind="metal", color=(0.045, 0.045, 0.05), roughness=0.45),
    "graphite": dict(kind="metal", color=(0.20, 0.20, 0.22), roughness=0.4),
    "silver": dict(kind="metal", color=(0.70, 0.71, 0.73), roughness=0.3),
    "white_shell": dict(kind="plastic", color=(0.90, 0.90, 0.88), roughness=0.5),
    "top_plate": dict(kind="plastic", color=(0.16, 0.16, 0.18), roughness=0.6),
    "rubber": dict(kind="rubber", color=(0.03, 0.03, 0.03), roughness=0.8),
    "aluminium": dict(kind="metal", color=(0.78, 0.79, 0.80), roughness=0.35),
    "estop_red": dict(kind="plastic", color=(0.80, 0.08, 0.06), roughness=0.4),
    "camera": dict(kind="plastic", color=(0.12, 0.12, 0.13), roughness=0.5),
}


def down_quat(yaw=0.0, tilt=0.0):
    """Flange orientation (w, x, y, z) for a top-down grasp: approach (flange +z) along world -z, fingers closing
    along (cos yaw, sin yaw, 0); `tilt` pitches the approach towards +y (robots/yam_cart.down_quat)."""
    xa = np.array([math.cos(yaw), math.sin(yaw), 0.0])
    za = np.array([0.0, 0.0, -1.0])
    R = np.stack([xa, np.cross(za, xa), za], axis=1)
    c, s = math.cos(tilt), math.sin(tilt)
    Rx = np.array([[1.0, 0.0, 0.0], [0.0, c, -s], [0.0, s, c]])
    return Rx @ R


def grasp_R(yaw=0.0, tilt=0.0):
    """Flange orientation (3x3) for a grasp whose fingers close along the HORIZONTAL direction (cos yaw, sin yaw, 0):
    approach (flange +z) straight down, then pitched by `tilt` about the closing axis, leaning towards +y (away from
    the cart). The pad faces stay vertical for any tilt, so a tilted grasp still squeezes a flat-lying plug on its
    sides. For yaw = 0 this equals down_quat(0, tilt). yaw is expected in (-pi/2, pi/2]."""
    c = np.array([math.cos(yaw), math.sin(yaw), 0.0])
    th = tilt if c[0] >= 0 else -tilt
    a = np.array([-math.sin(th) * c[1], math.sin(th) * c[0], -math.cos(th)])
    return np.stack([c, np.cross(a, c), a], 1)


def short(label):
    return label.split("/")[-1]


# ---------------------------------------------------------------------------------------------- Newton model
def add_robot(b, link_hulls=True):
    """Add the cart to builder b (call before anything else). Returns a dict of indices."""
    assert b.body_count == 0, "the robot must be the first thing in the builder"
    b.add_mjcf(MJCF, enable_self_collisions=False, collapse_fixed_joints=False, parse_sites=False)
    nb = b.body_count
    bodies = {short(b.body_label[i]): i for i in range(nb)}
    joints = {short(b.joint_label[j]): j for j in range(b.joint_count)}
    qidx = {n: b.joint_q_start[j] for n, j in joints.items()}
    NC.make_kinematic(b, range(nb))
    import trimesh
    import mujoco
    mm = mujoco.MjModel.from_xml_path(MJCF)
    rgba = {mm.geom(i).name: mm.geom_rgba[i].copy() for i in range(mm.ngeom) if mm.geom(i).name}
    pads, palms, hulls = {}, {}, []
    shapes = list(range(b.shape_count))
    for s in shapes:  # preview colours = the MJCF's material colours (build_models.PALETTE)
        lab = short(b.shape_label[s])
        if lab in rgba and rgba[lab][3] > 0.99:
            b.shape_color[s] = tuple(float(x) for x in rgba[lab][:3])
    collide = int(newton.ShapeFlags.COLLIDE_SHAPES) | int(newton.ShapeFlags.COLLIDE_PARTICLES)
    for s in shapes:
        lab = short(b.shape_label[s])
        b.shape_material_kd[s] = 0.0
        if lab.endswith("_pad0"):
            side, finger = lab.split("_")[0], "_".join(lab.split("_")[1:3])
            pads.setdefault(side, {})[finger] = s
            b.shape_material_ke[s] = PAD_KE
            b.shape_material_mu[s] = PAD_MU
            b.shape_gap[s] = NC.CONTACT_GAP
        elif lab.endswith("_palm0"):
            palms[lab.split("_")[0]] = s
            b.shape_flags[s] = b.shape_flags[s] & ~int(newton.ShapeFlags.VISIBLE)  # collision box, not drawn
            b.shape_material_ke[s] = LINK_KE
            b.shape_material_mu[s] = LINK_MU
            b.shape_gap[s] = NC.CONTACT_GAP
        elif b.shape_flags[s] & collide:
            body = b.shape_body[s]
            name = short(b.body_label[body])
            b.shape_flags[s] = b.shape_flags[s] & ~collide  # off: cart boxes never reach anything; link meshes -> hulls
            if link_hulls and lab.endswith("_visual_col") and ("link" in name):
                src = b.shape_source[s]
                V = np.asarray(src.vertices, float) * np.asarray(b.shape_scale[s], float)
                hull = trimesh.convex.convex_hull(V)
                cfg = newton.ModelBuilder.ShapeConfig(density=0.0, ke=LINK_KE, kd=0.0, mu=LINK_MU, margin=0.0,
                                                      gap=NC.CONTACT_GAP, is_visible=False)
                hs = b.add_shape_convex_hull(body, xform=b.shape_transform[s],
                                             mesh=newton.Mesh(np.asarray(hull.vertices, np.float32),
                                                              np.asarray(hull.faces, np.int32).ravel()),
                                             cfg=cfg, label=f"{name}_hull")
                hulls.append(hs)
    # the robot never collides with itself (kinematic links; adjacent hulls overlap at the joints)
    col = [s for s in range(b.shape_count) if b.shape_flags[s] & collide]
    for i, a in enumerate(col):
        for c in col[i + 1:]:
            b.add_shape_collision_filter_pair(a, c)
    return dict(n_bodies=nb, bodies=bodies, joints=joints, qidx=qidx, pads=pads, palms=palms, hulls=hulls,
                robot_shapes=list(range(b.shape_count)))


def robot_only_model(device=None):
    b = newton.ModelBuilder(gravity=0.0)
    info = add_robot(b, link_hulls=False)
    return b.finalize(device=device, requires_grad=False), info


# ------------------------------------------------------------------------------------------ MuJoCo kinematics
class Kin:
    """IK / FK on the MJCF with MuJoCo (CPU). q vectors are full 19-coordinate MJCF qpos."""

    def __init__(self):
        import mujoco
        self.mj = mujoco
        self.m = mujoco.MjModel.from_xml_path(MJCF)
        self.d = mujoco.MjData(self.m)
        self.jq = {self.m.joint(i).name: int(self.m.jnt_qposadr[i]) for i in range(self.m.njnt)}
        self.jd = {self.m.joint(i).name: int(self.m.jnt_dofadr[i]) for i in range(self.m.njnt)}
        self.arm_q = {s: np.array([self.jq[f"{s}_joint{k}"] for k in range(1, 7)]) for s in SIDES}
        self.arm_d = {s: np.array([self.jd[f"{s}_joint{k}"] for k in range(1, 7)]) for s in SIDES}
        self.finger_q = {s: np.array([self.jq[f"{s}_joint7"], self.jq[f"{s}_joint8"]]) for s in SIDES}
        self.flange = {s: self.m.body(f"{s}_gripper").id for s in SIDES}
        self.lo = self.m.jnt_range[:, 0].copy()
        self.hi = self.m.jnt_range[:, 1].copy()
        self.jnt_of_q = {}
        for i in range(self.m.njnt):
            self.jnt_of_q[int(self.m.jnt_qposadr[i])] = i

    def q_home(self):
        q = np.zeros(self.m.nq)
        q[self.jq["base_y"]] = layout.ROBOT_MOUNT["cart_center_y"]
        for s in SIDES:
            q[self.arm_q[s]] = [0.0, 1.0, 1.0, 0.0, 0.0, 0.0]
            q[self.finger_q[s]] = FINGER_Q_MAX
        for s in SIDES:
            qa, err = self.ik(s, HOME_TCP[s], down_quat(0.0), q)
            assert err < 1e-4, f"home IK {s}: {err}"
            q[self.arm_q[s]] = qa
        return q

    def _fwd(self, q):
        self.d.qpos[:] = q
        self.mj.mj_kinematics(self.m, self.d)
        self.mj.mj_comPos(self.m, self.d)

    def tcp(self, side, q):
        """TCP world position and flange rotation for full q."""
        self._fwd(q)
        b = self.flange[side]
        R = self.d.xmat[b].reshape(3, 3).copy()
        return self.d.xpos[b] + R @ TCP_OFFSET, R

    def pad_boxes(self, side, q):
        """The two fingertip pad boxes of `side` at full q: [(centre, R, half extents)] (MuJoCo geoms *_pad0)."""
        self._fwd(q)
        out = []
        for f in ("tip_left", "tip_right"):
            gid = self.m.geom(f"{side}_{f}_pad0").id
            out.append((self.d.geom_xpos[gid].copy(), self.d.geom_xmat[gid].reshape(3, 3).copy(),
                        self.m.geom_size[gid].copy()))
        return out

    def body_poses(self, q):
        """{body name: (pos, R)} for every MJCF body."""
        self._fwd(q)
        return {self.m.body(i).name: (self.d.xpos[i].copy(), self.d.xmat[i].reshape(3, 3).copy())
                for i in range(1, self.m.nbody)}

    def ik(self, side, pos, R_target, q_seed, iters=300, tol=1e-6):
        """Damped least squares on the 6 arm joints of `side`: TCP to `pos`, flange to R_target. Returns
        (q_arm, error) with error = |dp| + 0.05 |drot|."""
        q = np.array(q_seed, float).copy()
        ia, idd = self.arm_q[side], self.arm_d[side]
        jacp = np.zeros((3, self.m.nv))
        jacr = np.zeros((3, self.m.nv))
        pos = np.asarray(pos, float)
        lam = 1e-3
        err = np.inf
        for _ in range(iters):
            p, R = self.tcp(side, q)
            ep = pos - p
            Re = R_target @ R.T
            ang = math.acos(float(np.clip((np.trace(Re) - 1) / 2, -1, 1)))
            if ang < 1e-9:
                er = np.zeros(3)
            else:
                er = ang / (2 * math.sin(ang)) * np.array([Re[2, 1] - Re[1, 2], Re[0, 2] - Re[2, 0], Re[1, 0] - Re[0, 1]])
            err = float(np.linalg.norm(ep) + 0.05 * np.linalg.norm(er))
            if np.linalg.norm(ep) < tol and np.linalg.norm(er) < 20 * tol:
                break
            self.mj.mj_jac(self.m, self.d, jacp, jacr, p, self.flange[side])
            J = np.vstack([jacp[:, idd], 0.2 * jacr[:, idd]])
            e = np.concatenate([ep, 0.2 * er])
            dq = J.T @ np.linalg.solve(J @ J.T + lam * np.eye(6), e)
            n = np.abs(dq).max()
            if n > 0.2:
                dq *= 0.2 / n
            q[ia] += dq
            for k, qi in enumerate(ia):
                jn = self.jnt_of_q[int(qi)]
                if self.m.jnt_limited[jn]:
                    q[qi] = np.clip(q[qi], self.lo[jn], self.hi[jn])
        return q[ia].copy(), err


def export_parts():
    """[(object_name, link_name, mesh_path, material)] for the robot's per-(link, material) OBJs (link frame, z-up, m),
    generated by robots/yam_cart.export_parts (same names as the Genesis stations export)."""
    parts = json.load(open(EXPORT_INDEX))
    return [(f"robot/{p['link']}" + (f"/{p['material']}" if p["multi"] else ""), p["link"], p["mesh"],
             dict(MATERIALS[p["material"]])) for p in parts]
